def ing(identifier, name, cn_name, category, functions, **kwargs):
    item = {
        "id": identifier,
        "name": name,
        "cn_name": cn_name,
        "category": category,
        "functions": functions,
        "ph_min": 2.0,
        "ph_max": 9.0,
        "max_process_temp_c": 250.0,
        "water_solubility": "high",
        "typical_pct": [0.1, 5.0],
        "max_pct": 30.0,
        "aw_effect": 0.0,
        "texture_effect": "neutral",
        "allergen": False,
        "food_additive": False,
        "e_number": None,
        "clean_label": True,
        "cost_index": 2,
        "food_safe": True,
        "regulatory": "demo_prior_verify_local_law",
        "notes_cn": "",
        "evidence": ["Fennema's Food Chemistry, 5th ed.", "USDA FoodData Central (composition reference)"],
        "source_type": "curated_prior",
        "confidence": "medium",
    }
    item.update(kwargs)
    return item


