for system in SYSTEMS:
    recipe = system["base_recipe"]
    water_entry = next((item for item in recipe if item[0] == "water"), None)
    total_other = sum(float(item[1]) for item in recipe if item[0] != "water")
    if water_entry is not None:
        water_entry[1] = round(max(5.0, 100.0 - total_other), 2)
    for item in recipe:
        if item[0] not in {ingredient["id"] for ingredient in INGREDIENTS}:
            raise SystemExit(f"unknown ingredient {item[0]} in {system['id']}")
    system["water_basis"] = water_entry is not None
    system["source_type"] = "curated_food_system_template"
    system["confidence"] = "medium"
    system["regulatory_note"] = "模板仅用于配方筛选与工艺讨论，不是法规配方；需按销售地法规和真实中试验证。"

